{"code": "import os

# Check if test dataset has actual images or LFS pointers
test_dir = 'data_small_test'
if os.path.exists(test_dir):
    classes = [d for d in os.listdir(test_dir) if os.path.isdir(os.path.join(test_dir, d))]
    for class_name in classes[:2]:
        class_path = os.path.join(test_dir, class_name)
        files = os.listdir(class_path)[:3]
        print(f"\n{class_name}:")
        for fname in files:
            fpath = os.path.join(class_path, fname)
            with open(fpath, 'rb') as f:
                header = f.read(30)
                if b'git-lfs' in header:
                    print(f"  {fname}: LFS pointer file")
                else:
                    print(f"  {fname}: appears to be actual image")
else:
    print("Test dataset directory not found")"}

